&lt;ul class=&quot;s-list-disc s-pb-2 s-pl-6 s-flex s-flex-col s-gap-1 s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;
&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;Permanent position&lt;/li&gt;
&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;Tech stack: Kubernetes, Prometheus, OpenTelemetry, Loki, ArgoCD, Ruby, Python, Go&lt;/li&gt;
&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;Full-time&lt;/li&gt;
&lt;li class=&quot;s-break-words s-text-foreground dark:s-text-foreground-night s-text-base s-leading-relaxed&quot;&gt;Paris, France&lt;/li&gt;
